122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
125	        normalizeAddress(ownerFieldsDto);
126	        validateRequiredFields(ownerFieldsDto);
127	        validatePostcode(ownerFieldsDto);
128	        normalizeTelephone(ownerFieldsDto);
129	        normalizeEmail(ownerFieldsDto);
130	        rejectDuplicateIdentity(ownerFieldsDto);
131	        rejectCityAtCapacity(ownerFieldsDto.getCity());
132	        rejectFutureRegistrationDate(ownerFieldsDto);
133	        defaultRegistrationDate(ownerFieldsDto);
134	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
135	        HttpHeaders headers = new HttpHeaders();
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        assignCustomerCode(owner);
138	        assignHouseholdId(owner);
139	        assignHouseholdMemberCount(owner);
140	        assignNamesakeCount(owner);
141	        assignMembershipNumber(owner);
142	        assignBulkSignupWarning(owner);
143	        assignPossibleDuplicate(owner);
144	        this.clinicService.saveOwner(owner);
145	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
146	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        headers.setLocation(UriComponentsBuilder.newInstance()
149	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
150	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
151	    }
