235	    /**
236	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
237	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
238	     * Validation already rejects {@code null} values and the pattern-constrained fields
239	     * when blank, but {@code address} and {@code city} have no pattern, so a
240	     * whitespace-only value would otherwise slip through.
241	     *
242	     * @param ownerFieldsDto the submitted owner fields
243	     * @throws RequiredFieldsMissingException if any required field is missing or blank
244	     */
245	    /**
246	     * Common street-type abbreviations expanded during address normalization. Keys are the
247	     * upper-cased abbreviation tokens; values are their canonical expansions.
248	     */
249	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
250	        "ST", "STREET",
251	        "RD", "ROAD",
252	        "AVE", "AVENUE");
253	
254	    /**
255	     * Normalizes the submitted address on create and writes the canonical value back onto the
256	     * request so it is persisted, echoed back, and used for every downstream address comparison
257	     * (household duplicate detection and the household id). The value is trimmed, internal
258	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
259	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
260	     * {@code null} address is left untouched so the required-field check can report it as missing.
261	     *
262	     * @param ownerFieldsDto the submitted owner fields
263	     */
264	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
265	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
266	    }
267	
268	    /**
269	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
270	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
271	     * expanded to its full form. A {@code null} value is returned unchanged.
272	     *
273	     * @param raw the address to canonicalize, possibly {@code null}
274	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
275	     */
276	    private static String normalizeAddress(String raw) {
277	        if (raw == null) {
278	            return null;
279	        }
280	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
281	        if (collapsed.isEmpty()) {
282	            return collapsed;
283	        }
284	        String[] tokens = collapsed.split(" ");
285	        StringBuilder sb = new StringBuilder(collapsed.length());
286	        for (int i = 0; i < tokens.length; i++) {
287	            if (i > 0) {
288	                sb.append(' ');
289	            }
290	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
291	        }
292	        return sb.toString();
293	    }
294	
295	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
296	        List<String> errors = new ArrayList<>();
297	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
298	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
299	        requireText("address", ownerFieldsDto.getAddress(), errors);
300	        requireText("city", ownerFieldsDto.getCity(), errors);
301	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
302	        if (!errors.isEmpty()) {
303	            throw new RequiredFieldsMissingException(errors);
304	        }
305	    }
306	
307	    private static void requireText(String field, String value, List<String> errors) {
308	        if (value == null || value.isBlank()) {
309	            errors.add(field);
310	        }
311	    }
312	
313	    /**
314	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
315	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
316	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
317	     */
318	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
319	        "NSW", new int[] {2000, 2099},
320	        "VIC", new int[] {3000, 3099},
321	        "QLD", new int[] {4000, 4099});
322	
323	    /**
324	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
325	     * {@code null} value is accepted. When present it has already been constrained to four digits
326	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
327	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
328	     * the postcode must fall within that region's inclusive range
329	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
330	     *
331	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
332	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
333	     *                                  city's region
334	     */
335	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
336	        String postcode = ownerFieldsDto.getPostcode();
337	        if (postcode == null) {
338	            return;
339	        }
340	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
341	            .regionFor(ownerFieldsDto.getCity());
342	        int[] range = REGION_POSTCODE_RANGE.get(region);
343	        if (range == null) {
344	            return;
345	        }
346	        int value = Integer.parseInt(postcode);
347	        if (value < range[0] || value > range[1]) {
348	            throw new InvalidPostcodeException(postcode);
349	        }
350	    }
351	
352	    /**
353	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
354	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
355	     * and echoed back in that form.
356	     *
357	     * @param ownerFieldsDto the submitted owner fields
358	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
359	     *                                        valid E.164 number
360	     */
361	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
362	        String e164 = toE164(ownerFieldsDto.getTelephone());
363	        if (e164 == null) {
364	            throw new RequiredFieldsMissingException(List.of("telephone"));
365	        }
366	        ownerFieldsDto.setTelephone(e164);
367	    }
368	
369	    /**
370	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
371	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
372	     * and country code are present they are kept; otherwise country code {@code '+61'} is
373	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
374	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
375	     * the national-number length must match the country: {@code '+61'} (Australia) requires
376	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
377	     *
378	     * @param raw the submitted telephone, possibly {@code null}
379	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
380	     */
381	    private static String toE164(String raw) {
382	        if (raw == null) {
383	            return null;
384	        }
385	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
386	        String digits;
387	        if (cleaned.startsWith("+")) {
388	            digits = cleaned.substring(1);
389	        } else {
390	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
391	            digits = "61" + national;
392	        }
393	        if (!digits.matches("[0-9]{8,15}")) {
394	            return null;
395	        }
396	        if (digits.startsWith("61")) {
397	            // Australia: exactly 9 national digits after the '+61' country code.
398	            if (digits.length() - 2 != 9) {
399	                return null;
400	            }
401	        } else if (digits.startsWith("1")) {
402	            // NANP: exactly 10 national digits after the '+1' country code.
403	            if (digits.length() - 1 != 10) {
404	                return null;
405	            }
406	        }
407	        return "+" + digits;
408	    }
409	
410	    /**
411	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
412	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
413	     * each stored owner's telephone is normalized the same way before comparison so differing
414	     * input formats collapse to the same value.
415	     *
416	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
417	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
418	     *                                     same E.164 telephone
419	     */
420	    /**
421	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
422	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
423	     * the parts may contain whitespace or a second {@code @}.
424	     */
425	    private static final Pattern EMAIL_PATTERN =
426	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
427	
428	    /**
429	     * Normalizes the submitted email when present: the value is trimmed, required to be a
430	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
431	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
432	     *
433	     * @param ownerFieldsDto the submitted owner fields
434	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
435	     */
436	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
437	        String email = ownerFieldsDto.getEmail();
438	        if (email == null) {
439	            return;
440	        }
441	        String trimmed = email.strip();
442	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
443	            throw new InvalidEmailException(email);
444	        }
445	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
446	    }
447	
448	    /**
449	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
450	     * date. A registration may be back-dated but never post-dated. The check is made against the
451	     * value as supplied, before any defaulting or business-day roll (see
452	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
453	     * to the server date).
454	     *
455	     * @param ownerFieldsDto the submitted owner fields
456	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
457	     *                                         after the server's current date
458	     */
459	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
460	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
461	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
462	            throw new FutureRegistrationDateException(supplied);
463	        }
464	    }
465	
466	    /**
467	     * Establishes the effective registration date on create and rolls it onto a business day.
468	     * When the client does not supply a {@code registrationDate} it defaults to the server's
469	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
470	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
471	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
472	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
473	     * the membership number's year segment and the daily create-limit).
474	     *
475	     * @param ownerFieldsDto the submitted owner fields
476	     */
477	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
478	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
479	        if (effective == null) {
480	            effective = LocalDate.now();
481	        }
482	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
483	    }
484	
485	    /**
486	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
487	     * following Monday; any weekday is returned unchanged.
488	     *
489	     * @param date the date to adjust
490	     * @return the same date when it is a weekday, otherwise the next Monday
491	     */
492	    private static LocalDate toBusinessDay(LocalDate date) {
493	        return switch (date.getDayOfWeek()) {
494	            case SATURDAY -> date.plusDays(2);
495	            case SUNDAY -> date.plusDays(1);
496	            default -> date;
497	        };
498	    }
499	
500	    /**
501	     * Assigns the owner's {@code customerCode} on create, formatted
502	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
503	     * (preferring the postcode range, falling back to the city — the same derivation that yields
504	     * the owner's {@code locality}, see
505	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
506	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
507	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
508	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
509	     * customer code only when their normalized telephone and last name both match.
510	     *
511	     * @param owner the owner being created (with its {@code postcode}, {@code city},
512	     *              {@code telephone} and {@code lastName} already set)
513	     */
514	    private void assignCustomerCode(Owner owner) {
515	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
516	            .regionFor(owner.getPostcode(), owner.getCity());
517	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
518	            .substring(0, 8).toUpperCase(Locale.ROOT);
519	        owner.setCustomerCode(region + "-" + hash8);
520	    }
521	
522	    /**
523	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
524	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
525	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
526	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
527	     * canonicalized fields, every owner in the same household — including one joining an existing
528	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
529	     * order.
530	     *
531	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
532	     */
533	    private void assignHouseholdId(Owner owner) {
534	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
535	    }
536	
537	    /**
538	     * Derives the stable {@code householdId} for the given {@code lastName} and {@code address}:
539	     * {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the SHA-256
540	     * digest of the collapsed {@code lastName} and {@code address} (see {@link #collapse}) joined
541	     * by a {@code '\n'}. Because it is derived purely from those two canonicalized fields, every
542	     * owner in the same household receives the same value, independent of create order. Shared by
543	     * {@link #assignHouseholdId} (which persists it) and {@link #identityKeyFor} (which folds it
544	     * into the identity key for duplicate detection).
545	     *
546	     * @param lastName the owner's last name
547	     * @param address  the owner's address
548	     * @return the derived household id
549	     */
550	    private static String householdIdFor(String lastName, String address) {
551	        String key = collapse(lastName) + "\n" + collapse(address);
552	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
553	    }
554	
555	    /**
556	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
557	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
558	     * after this create. Because {@code householdId} is derived from the owner's collapsed
559	     * {@code lastName} and {@code address} (see {@link #assignHouseholdId}), the count reflects every
560	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
561	     * The count is taken before this owner is persisted, so it is one more than the number of
562	     * existing household members.
563	     *
564	     * @param owner the owner being created (with its {@code householdId} already assigned)
565	     */
566	    private void assignHouseholdMemberCount(Owner owner) {
567	        String householdId = owner.getHouseholdId();
568	        long existing = this.clinicService.findAllOwners().stream()
569	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
570	            .count();
571	        owner.setHouseholdMemberCount((int) (existing + 1));
572	    }
573	
574	    /**
575	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
576	     * already share this owner's {@code firstName} and {@code lastName}, compared
577	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
578	     * pre-existing namesakes.
579	     *
580	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
581	     */
582	    private void assignNamesakeCount(Owner owner) {
583	        String firstName = owner.getFirstName();
584	        String lastName = owner.getLastName();
585	        long count = this.clinicService.findAllOwners().stream()
586	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
587	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
588	            .count();
589	        owner.setNamesakeCount((int) count);
590	    }
591	
592	    /**
593	     * Assigns the owner's {@code membershipNumber} on create, formatted
594	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
595	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
596	     * (e.g. {@code 'NSW-A1B2C3D4-M26'}). Derived purely from the owner's own fields, so both
597	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
598	     *
599	     * @param owner the owner being created (with its {@code customerCode} and
600	     *              {@code registrationDate} already set)
601	     */
602	    private void assignMembershipNumber(Owner owner) {
603	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
604	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
605	    }
606	
607	    /**
608	     * The number of owners that must already carry a registration date before a subsequent
609	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
610	     * once the count of owners already registered on that day <em>exceeds</em> this value.
611	     */
612	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
613	
614	    /**
615	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
616	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
617	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
618	     * existing owners before this one is persisted, so it reflects only the owners already
619	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
620	     *
621	     * @param owner the owner being created (with its {@code registrationDate} already set)
622	     */
623	    private void assignBulkSignupWarning(Owner owner) {
624	        LocalDate registrationDate = owner.getRegistrationDate();
625	        long count = this.clinicService.findAllOwners().stream()
626	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
627	            .count();
628	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
629	    }
630	
631	    /**
632	     * Assigns the owner's soft-match duplicate flags on create. The create has already passed
633	     * {@link #rejectDuplicateIdentity}, so this owner is not a hard duplicate. It is a
634	     * <em>possible</em> duplicate when an existing owner shares its {@code lastName} (compared
635	     * case-insensitively) and its {@code postcode} but has a <em>different</em> normalized
636	     * {@code telephone}: {@code possibleDuplicate} is set {@code true} and
637	     * {@code possibleDuplicateOf} to that owner's id (the earliest such owner by id when several
638	     * match). Otherwise {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf}
639	     * is left unset. The scan is taken over the existing owners before this one is persisted.
640	     *
641	     * @param owner the owner being created (with its {@code lastName}, {@code postcode} and
642	     *              already-normalized {@code telephone} set)
643	     */
644	    private void assignPossibleDuplicate(Owner owner) {
645	        String lastName = owner.getLastName();
646	        String postcode = owner.getPostcode();
647	        String telephone = owner.getTelephone();
648	        Integer matchId = null;
649	        if (lastName != null && postcode != null && telephone != null) {
650	            matchId = this.clinicService.findAllOwners().stream()
651	                .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
652	                .filter(existing -> postcode.equals(existing.getPostcode()))
653	                .filter(existing -> !telephone.equals(existing.getTelephone()))
654	                .map(Owner::getId)
655	                .filter(id -> id != null)
656	                .min(Integer::compareTo)
657	                .orElse(null);
658	        }
659	        owner.setPossibleDuplicate(matchId != null);
660	        owner.setPossibleDuplicateOf(matchId);
661	    }
662	
663	    /**
664	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
665	     *
666	     * @param value the string to hash
667	     * @return the 64-character lower-case hex digest
668	     */
669	    private static String sha256Hex(String value) {
670	        try {
671	            byte[] digest = MessageDigest.getInstance("SHA-256")
672	                .digest(value.getBytes(StandardCharsets.UTF_8));
673	            StringBuilder sb = new StringBuilder(digest.length * 2);
674	            for (byte b : digest) {
675	                sb.append(String.format("%02x", b));
676	            }
677	            return sb.toString();
678	        }
679	        catch (NoSuchAlgorithmException e) {
680	            throw new IllegalStateException("SHA-256 not available", e);
681	        }
682	    }
683	
684	    /**
685	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
686	     * owner. This single key consolidates what used to be three separate duplicate checks
687	     * (telephone, email and household): the key is
688	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
689	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
690	     * matches an existing owner's. Because the telephone is part of the key, two members of the
691	     * same household (same {@code householdId}) with different telephones have different identity
692	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
693	     * and email have already been normalized by {@link #normalizeTelephone} and
694	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
695	     * input formats collapse to the same value.
696	     *
697	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
698	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
699	     *                                    whole identity key
700	     */
701	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
702	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress(),
703	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
704	        boolean duplicate = this.clinicService.findAllOwners().stream()
705	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getAddress(),
706	                owner.getTelephone(), owner.getEmail()))
707	            .anyMatch(identityKey::equals);
708	        if (duplicate) {
709	            throw new DuplicateIdentityException(identityKey);
710	        }
711	    }
712	
713	    /**
714	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
715	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
716	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
717	     * absent), and the {@code householdId} is derived from the collapsed {@code lastName} and
718	     * {@code address} the same way {@link #assignHouseholdId} assigns it (see
719	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
720	     * their whole identities match, regardless of the exact input formats.
721	     *
722	     * @param lastName  the owner's last name
723	     * @param address   the owner's address
724	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
725	     * @param email     the owner's email, possibly {@code null}
726	     * @return the canonical identity key
727	     */
728	    private static String identityKeyFor(String lastName, String address, String telephone, String email) {
729	        String normalizedTelephone = toE164(telephone);
730	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
731	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
732	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, address);
733	    }
734	
735	    /**
736	     * The maximum number of owners permitted in a single city. A create is rejected once the
737	     * owner's city already contains this many owners.
738	     */
739	    private static final long CITY_CAPACITY = 50;
740	
741	    /**
742	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
743	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
744	     * before this owner is persisted.
745	     *
746	     * @param city the submitted city
747	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
748	     */
749	    private void rejectCityAtCapacity(String city) {
750	        long count = this.clinicService.findAllOwners().stream()
751	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
752	            .count();
753	        if (count >= CITY_CAPACITY) {
754	            throw new CityAtCapacityException(city);
755	        }
756	    }
757	
758	    /**
759	     * The maximum number of owners permitted to be created in a single day. A create is
760	     * rejected once this many owners already carry today's {@code registrationDate}.
761	     */
762	    private static final long DAILY_LIMIT = 100;
763	
764	    /**
765	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
766	     * business day as their {@code registrationDate}. The day counted against is this create's
767	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
768	     * so owners are counted per adjusted business day. The count is taken before this owner is
769	     * persisted.
770	     *
771	     * @param businessDay the effective, business-day-adjusted registration date of this create
772	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
773	     */
774	    private void rejectDailyLimit(LocalDate businessDay) {
775	        long count = this.clinicService.findAllOwners().stream()
776	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
777	            .count();
778	        if (count >= DAILY_LIMIT) {
779	            throw new DailyOwnerLimitExceededException(businessDay);
780	        }
781	    }
782	
783	    /**
784	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
785	     * every internal run of whitespace is collapsed to a single space, and the result is
786	     * lower-cased. A {@code null} value collapses to the empty string.
787	     *
788	     * @param value the value to canonicalize, possibly {@code null}
789	     * @return the collapsed, lower-cased value
790	     */
791	    private static String collapse(String value) {
792	        if (value == null) {
793	            return "";
794	        }
795	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
796	    }
797	
798	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
799	    @Override
800	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
801	        Owner owner = this.clinicService.findOwnerById(ownerId);
802	        if (owner != null) {
803	            Pet pet = owner.getPet(petId);
804	            if (pet != null) {
805	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
806	            }
807	        }
808	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
809	    }
810	}
